-- Deities and Demigods: Pharaonic pantheon divine stat blocks, batch B.
-- Source: Deities and Demigods (2002), Chapter 5, pp. 144-149.
-- Printed 3.0 statistics remain source-of-truth; official 3.5 conversion deltas are recorded separately.

INSERT OR IGNORE INTO dnd35_sources
  (id,slug,name,abbreviation,publisher,system,edition,description,url,is_official,is_homebrew,owner_user_id)
VALUES ('dd-3.0','deities-and-demigods-3-0','Deities and Demigods','DD','Wizards of the Coast','dnd','3.0',
        'Deities and Demigods (2002): divine ranks, pantheons, salient divine abilities, divine minions, domains, spells, monsters, prestige classes, and ascension.',NULL,1,0,NULL);

UPDATE dnd35_deities SET symbol='Image of the deity' WHERE source_id='dd-3.0' AND slug='bes' AND owner_user_id IS NULL;
UPDATE dnd35_deities SET symbol='Horned cow''s head with a lunar disk' WHERE source_id='dd-3.0' AND slug='hathor' AND owner_user_id IS NULL;
UPDATE dnd35_deities SET symbol='A step pyramid' WHERE source_id='dd-3.0' AND slug='imhotep' AND owner_user_id IS NULL;
UPDATE dnd35_deities SET symbol='Ankh and star' WHERE source_id='dd-3.0' AND slug='isis' AND owner_user_id IS NULL;

