 in labor, every game of chance, and any musical performance heard by at least 500 people.","automaticActions":{"skills":["Bluff","Disguise","Hide"],"freeActionDcMaximum":20,"maximumPerRound":5},"createMagicItems":{"scope":"any magic item granting a luck bonus","maximumMarketPriceGp":30000},"avatarStatus":"No Avatar salient divine ability is present in the printed stat block; no avatar stat block is created.","revision3_5":{"alignmentSubtypes":["chaotic"],"damageReduction":"20/epic","fireResistance":12,"sonicImmunityFromSalientAbility":true,"additionalOutsiderSkillPoints":true,"bard":{"inspireCourage":"Revised bard 20 inspire courage bonus applies.","newMusicEffects":["song of freedom","inspire heroics","mass suggestion"],"additionalSkillPoints":40},"rogue":"Additional +2 against traps.","defunctSkills":["Pick Pocket -> Sleight of Hand"]}}'),

('dd-statblock-hathor','Hathor Divine Stat Block','145-147',
