ce.","skillFocus":"Use revised +3 Skill Focus bonus.","defunctSkills":["Alchemy -> Craft (alchemy)"]}}'),

('dd-statblock-isis','Isis Divine Stat Block','148-149',
 'Isis is the divine-rank-17 greater Pharaonic deity of fertility, magic, marriage, and life-giving waters.',
 '{"deitySlug":"isis","pantheon":"pharaonic","sourceEdition":"3.0","rankBand":"greater","divineRank":17,"symbol":"Ankh and star","homePlane":"The Offering Fields","alignment":"NG","classes":[{"class":"Wizard","level":20},{"class":"Cleric","level":20}],"creature":{"type":"Outsider","size":"Medium","hitDice":"20d8+180 outsider + 20d4+180 wizard + 20d8+180 cleric","hitPoints":940,"initiative":14,"speed":{"land":60},"armorClass":{"total":77,"dexterity":10,"divine":17,"natural":30,"deflection":10},"face":"5 ft. by 5 ft.","reachFeet":5},"attacks":{"spellTouch":{"melee":66,"ranged":67},"greaterDeityAlways20OnAttacks":true,"greaterDeityMaximumSpellDamage":true},"saves":{"fort":58,"ref":59,"will":60,"greaterDeityAlways20":true},"abilities":{"str":28,"dex":30,"con":29,"int":44,"wis":32,"cha":30},"specialAttacks":{"turnUndeadPerDay":13},"specialQualities":{"printedDamageReduction":"52/+4","printedSonicResistance":37,"fastHealing":37,"spellResistance":69,"divineAura":{"radiusMiles":17,"dc":37},"familiar":"birds","teleportWithoutErrorAtWill":true,"planeShiftAtWill":true},"salientDivineAbilities":["Alter Reality","Arcane Mastery","Area Divine Shield","Automatic Metamagic (quicken wizard spells)","Craft Artifact","Create Greater Object","Create Object","Divine Creation","Divine Dodge","Divine Fast Healing","Divine Shield","Divine Skill Focus (Spellcraft)","Divine Spellcasting","Extra Domain (Water)","Extra Energy Immunity (fire)","Gift of Life","Increased Energy Resistance (sonic)","Increased Spell Resistance","Instant Counterspell","Life and Death","See Magic","Spontaneous Wizard Spells"],"domainPowers":{"goodSpellsCasterLevelBonus":1,"magicDomainUseItemsAsWizardLevel":30,"protectiveWardUsesPerDay":17,"protectiveWardResistanceBonus":20,"waterTurningUsesPerDay":17},"spellLikeAbilities":{"casterLevel":27,"goodCasterLevel":28,"saveDc":"37 + spell level"},"spellcasting":{"clericSpellsPerDayLevels0To11":"6/9/9/9/8/8/7/7/6/6/2/2","clericBaseDc":"23 + spell level","wizardSpellsPerDayLevels0To17":"4/9/8/8/8/8/7/7/7/7/3/3/3/3/2/2/2/2","wizardBaseDc":"29 + spell level"},"senses":{"normalRangeMiles":17,"remoteSenseAdditionalFocus":"any animal"},"portfolioSense":"All magic use, discovery/recording/sharing of spells or arcane knowledge, conception of any child, and every wedding, instantaneously and 17 weeks into past and future.","automaticActions":{"skills":"Any Knowledge skill, even untrained, or Spellcraft","printedFreeActionDcMaximum":47,"maximumPerRound":20,"sourceNote":"Unlike the generic rank-17 automatic-action limit of DC 30, Isis''s individual entry explicitly prints DC 47 or less; preserve the individual source value."},"createMagicItems":"Any kind of magic item.","avatarStatus":"No Avatar salient divine ability is present in the printed stat block; no avatar stat block is created.","revision3_5":{"alignmentSubtypes":["good"],"damageReduction":"30/epic","rankBasedFireResistance":22,"fireImmunityFromSalientAbility":true,"sonicResistance37Preserved":true,"additionalOutsiderSkillPoints":true,"wizardSpecialization":"Apply revised school-specialization rules where relevant.","divineSkillFocus":"Apply the official revised Divine Skill Focus treatment.","defunctSkills":["Alchemy -> Craft (alchemy)","Scry ranks reassigned"]}}')
)
INSERT INTO dnd35_rules
  (id,source_id,source_page,slug,name,description,rules_text,is_homebrew,owner_user_id,is_enabled,
   category,kind,is_variant,default_enabled,parent_slug,supersedes_slug,tags,mechanics)
SELECT
  'dd-rule-'||d.slug,'dd-3.0',d.page,d.slug,d.name,d.description,
  'Use the structured mechanics payload for the printed Deities and Demigods divine stat block. Printed 3.0 values remain source-of-truth; revision3_5 records official conversion deltas.',
  0,NULL,1,'deity','divine-stat-block',0,1,'dd-pharaonic-pantheon',NULL,
  '["deities-and-demigods","pharaonic","deity-stat-block","revision-3.5"]',
  d.mechanics
FROM desired d
WHERE NOT EXISTS (
  SELECT 1 FROM dnd35_rules r WHERE r.source_id='dd-3.0' AND r.slug=d.slug AND r.owner_user_id IS NULL
);
